function createBaseForkResponse(): ForkResponse {
  return { forkedAgentSessionId: "", title: "", messageCount: 0 };
}

export const ForkResponse: MessageFns<ForkResponse> = {
  encode(message: ForkResponse, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.forkedAgentSessionId !== "") {
      writer.uint32(10).string(message.forkedAgentSessionId);
    }
    if (message.title !== "") {
      writer.uint32(18).string(message.title);
    }
    if (message.messageCount !== 0) {
      writer.uint32(24).uint64(message.messageCount);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ForkResponse {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseForkResponse();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.forkedAgentSessionId = reader.string();
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.title = reader.string();
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.messageCount = longToNumber(reader.uint64());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): ForkResponse {
    return {
      forkedAgentSessionId: isSet(object.forkedAgentSessionId)
        ? globalThis.String(object.forkedAgentSessionId)
        : isSet(object.forked_agent_session_id)
        ? globalThis.String(object.forked_agent_session_id)
        : "",
      title: isSet(object.title) ? globalThis.String(object.title) : "",
      messageCount: isSet(object.messageCount)
        ? globalThis.Number(object.messageCount)
        : isSet(object.message_count)
        ? globalThis.Number(object.message_count)
        : 0,
    };
  },

  toJSON(message: ForkResponse): unknown {
    const obj: any = {};
    if (message.forkedAgentSessionId !== "") {
      obj.forkedAgentSessionId = message.forkedAgentSessionId;
    }
    if (message.title !== "") {
      obj.title = message.title;
    }
    if (message.messageCount !== 0) {
      obj.messageCount = Math.round(message.messageCount);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ForkResponse>, I>>(base?: I): ForkResponse {
    return ForkResponse.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ForkResponse>, I>>(object: I): ForkResponse {
    const message = createBaseForkResponse();
    message.forkedAgentSessionId = object.forkedAgentSessionId ?? "";
    message.title = object.title ?? "";
    message.messageCount = object.messageCount ?? 0;
    return message;
  },
};

